	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return st, NewRouter(st)
}

func doJSON(t *testing.T, handler http.Handler, method, path string, body any) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(method, path, reader)
	request.Header.Set("Content-Type", "application/json")
	handler.ServeHTTP(recorder, request)
	return recorder
}

func doRaw(t *testing.T, handler http.Handler, method, path, raw string) *httptest.ResponseRecorder {
	t.Helper()
	recorder := httptest.NewRecorder()
	request := httptest.NewRequest(method, path, bytes.NewBufferString(raw))
	request.Header.Set("Content-Type", "application/json")
	handler.ServeHTTP(recorder, request)
	return recorder
}

func expectErrorCode(t *testing.T, recorder *httptest.ResponseRecorder, status int, code string) {
	t.Helper()
	if recorder.Code != status {
		t.Fatalf("status = %d, want %d (body %s)", recorder.Code, status, recorder.Body.String())
	}
	var envelope struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(recorder.Body.Bytes(), &envelope); err != nil {
		t.Fatalf("decode error body %q: %v", recorder.Body.String(), err)
	}
	if envelope.Error.Code != code {
		t.Fatalf("code = %q, want %q", envelope.Error.Code, code)
	}
	if envelope.Error.Message == "" {
		t.Fatalf("error message is empty")
	}
	var top map[string]json.RawMessage
	if err := json.Unmarshal(recorder.Body.Bytes(), &top); err != nil {
		t.Fatalf("decode top level: %v", err)
	}
	if len(top) != 1 {
		t.Fatalf("error body has %d top-level fields, want only error", len(top))
	}
}

func expectTaskRecord(t *testing.T, recorder *httptest.ResponseRecorder, want map[string]any) {
	t.Helper()
	var top map[string]json.RawMessage
	if err := json.Unmarshal(recorder.Body.Bytes(), &top); err != nil {
		t.Fatalf("decode record %q: %v", recorder.Body.String(), err)
	}
	gotKeys := make([]string, 0, len(top))
	for key := range top {
		gotKeys = append(gotKeys, key)
	}
	sort.Strings(gotKeys)
	wantKeys := []string{"dependsOn", "id", "maxRetries", "workflow"}
	if len(gotKeys) != len(wantKeys) {
		t.Fatalf("record keys = %v, want %v", gotKeys, wantKeys)
	}
	for i, key := range wantKeys {
		if gotKeys[i] != key {
			t.Fatalf("record keys = %v, want %v", gotKeys, wantKeys)
		}
	}
	for key, wantValue := range want {
		var gotValue any
		if err := json.Unmarshal(top[key], &gotValue); err != nil {
			t.Fatalf("decode field %s: %v", key, err)
		}
		if !equalsJSON(gotValue, wantValue) {
			t.Fatalf("field %s = %v, want %v", key, gotValue, wantValue)
		}
	}
}

