		}(i)
	}
	wg.Wait()

	var created, okCount, conflicts int
	for _, status := range statuses {
		switch status {
		case http.StatusCreated:
			created++
		case http.StatusOK:
			okCount++
		case http.StatusConflict:
			conflicts++
		default:
			t.Fatalf("unexpected status %d", status)
		}
	}
	if created != 1 {
		t.Fatalf("created = %d, want exactly 1", created)
	}
	if created+okCount+conflicts != workers {
		t.Fatalf("unexpected status mix: %v", statuses)
	}

	var count int
	if err := st.DB().QueryRow(`SELECT COUNT(*) FROM tasks WHERE id='same'`).Scan(&count); err != nil {
		t.Fatalf("count: %v", err)
	}
	if count != 1 {
		t.Fatalf("stored rows = %d, want 1", count)
	}
}
