func TestConcurrentRegisterSameIDKeepsSingleRow(t *testing.T) {
	ctx := context.Background()
	st := openTestStore(t)
	const workers = 32
	var wg sync.WaitGroup
	createdCount := make([]bool, workers)
	errs := make([]error, workers)
	wg.Add(workers)
	for i := range workers {
		go func(i int) {
			defer wg.Done()
			_, created, err := st.RegisterTask(ctx, sampleTask("same"))
			createdCount[i] = created
			errs[i] = err
		}(i)
	}
	wg.Wait()

	var created int
	for i := range workers {
		if errs[i] != nil {
			t.Fatalf("worker %d: %v", i, errs[i])
		}
		if createdCount[i] {
			created++
		}
	}
	if created != 1 {
		t.Fatalf("created = %d, want exactly 1", created)
	}

	var count int
	if err := st.db.QueryRow(`SELECT COUNT(*) FROM tasks WHERE id='same'`).Scan(&count); err != nil {
		t.Fatalf("count: %v", err)
	}
	if count != 1 {
		t.Fatalf("rows = %d, want 1", count)
	}
}

